mapper.update:
UPDATE calc_task SET progress_current = GREATEST(progress_current, #{percent}),
    progress_total = 100, phase = #{phase}, heartbeat_at = CURRENT_TIMESTAMP(3)
WHERE id = #{id} AND status = 'RUNNING' AND worker_id = #{workerId} AND version = #{version}

UPDATE calc_task SET status = #{status}, result_resource_id = #{resultResourceId},
    finished_at = CURRENT_TIMESTAMP(3), version = version + 1
WHERE id = #{id} AND version = #{version}

UPDATE calc_task SET status = #{status}, error_code = #{errorCode}, error_message = #{errorMessage},
    finished_at = CURRENT_TIMESTAMP(3), version = version + 1
WHERE id = #{id} AND version = #{version}
